import type { StockAssetMeta } from '@parlante/shared';

/**
 * Catalogue of built-in stock assets (backgrounds, music) GENERATED BY CODE — no downloaded or
 * third-party media. Owner: content.
 *
 * Isomorphic: this file only holds metadata, so templates and the web can import ids. The
 * bytes are produced on demand in Node by `getStockAssetData` (./node), which the API serves at
 * `GET /api/stock-assets/:stockId/file` and the worker reads when rendering.
 *
 * Add an asset = add its metadata here and its generator in ./node/generators.ts.
 */
export const STOCK_ASSETS: readonly StockAssetMeta[] = [
  {
    id: 'bg-aurora',
    kind: 'image',
    category: 'background',
    name: 'Aurora',
    tags: ['degradado', 'violeta', 'abstracto'],
    mimeType: 'image/png',
    width: 1920,
    height: 1080,
    durationMs: null,
  },
];

export function listStockAssets(): StockAssetMeta[] {
  return [...STOCK_ASSETS];
}

export function getStockAssetMeta(stockId: string): StockAssetMeta | null {
  return STOCK_ASSETS.find((a) => a.id === stockId) ?? null;
}
